fn solve(n: i8) -> Vec<i8> {
    // Assume n >= 1 as stated.
    let weeks = n / 7;
    let r = n % 7;

    // min extra days off in the remaining r days: max(0, r - 5)
    let min_extra = (r - 5).max(0);

    // max extra days off in the remaining r days: min(2, r)
    let max_extra = r.min(2);

    let min_days_off = 2 * weeks + min_extra;
    let max_days_off = 2 * weeks + max_extra;

    vec![min_days_off, max_days_off]
}